CREATE TABLE IF NOT EXISTS gis_spatial_feature_backfill_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), primary_provider text NOT NULL, comparison_provider text NOT NULL, primary_feature_count integer NOT NULL DEFAULT 0, comparison_feature_count integer NOT NULL DEFAULT 0, inserted_count integer NOT NULL DEFAULT 0, skipped_count integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'Pending', started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE INDEX IF NOT EXISTS idx_gis_spatial_feature_backfill_runs_status ON gis_spatial_feature_backfill_runs(status,started_at DESC);